     1	package com.pousadamarealta.service;
     2	
     3	import com.pousadamarealta.domain.*;
     4	
     5	import java.math.BigDecimal;
     6	import java.math.RoundingMode;
     7	import java.text.NumberFormat;
     8	import java.time.format.DateTimeFormatter;
     9	import java.util.Locale;
    10	
    11	public class CnpjDocumentGenerator implements DocumentGenerator {
    12	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    13	    private static final NumberFormat MONEY_FORMAT = NumberFormat.getCurrencyInstance(new Locale("pt", "BR"));
    14	
    15	    @Override
    16	    public Document generate(Reservation reservation, Room room, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
    17	        CnpjIdentification identification = (CnpjIdentification) reservation.getIdentification();
    18	        BigDecimal iss = total.multiply(new BigDecimal("0.05")).setScale(2, RoundingMode.HALF_EVEN);
    19	
    20	        StringBuilder text = new StringBuilder();
    21	        text.append("Fatura de hospedagem nº ").append(reservation.getId()).append("\n");
    22	        text.append("Empresa: ").append(identification.getCompanyName())
    23	            .append(" (CNPJ ").append(identification.getCnpj()).append(")\n");
    24	        text.append("Hóspede: ").append(reservation.getGuestName()).append("\n");
    25	        text.append("Quarto: ").append(room.getNumber()).append(" (").append(room.getType()).append(")\n");
    26	        text.append("Entrada: ").append(reservation.getCheckIn().format(DATE_FORMAT))
    27	            .append(" | Saída: ").append(reservation.getCheckOut().format(DATE_FORMAT))
    28	            .append(" | ").append(reservation.getNights())
    29	            .append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
    30	        text.append("Diárias: ").append(formatMoney(subtotal)).append("\n");
    31	
    32	        if (discount.compareTo(BigDecimal.ZERO) > 0) {
    33	            text.append("Desconto: ").append(formatMoney(discount)).append("\n");
    34	        }
    35	
    36	        text.append("Total: ").append(formatMoney(total)).append("\n");
    37	        text.append("ISS retido (5%): ").append(formatMoney(iss));
    38	
    39	        return new Document(
    40	            "Fatura de hospedagem",
    41	            reservation.getId(),
    42	            reservation.getGuestName(),
    43	            null,
    44	            identification.getCnpj(),
    45	            identification.getCompanyName(),
    46	            null,
    47	            null,
    48	            room.getNumber(),
    49	            room.getType(),
    50	            reservation.getCheckIn(),
    51	            reservation.getCheckOut(),
    52	            reservation.getNights(),
    53	            subtotal,
    54	            discount,
    55	            total,
    56	            text.toString()
    57	        );
    58	    }
    59	
    60	    private String formatMoney(BigDecimal amount) {
    61	        return MONEY_FORMAT.format(amount);
    62	    }
    63	}
