     6	import com.pousadamarealta.repository.RoomRepository;
     7	
     8	import java.math.BigDecimal;
     9	import java.time.LocalDate;
    10	import java.util.HashMap;
    11	import java.util.Map;
    12	
    13	public class ReservationService {
    14	    private final ReservationRepository reservationRepository;
    15	    private final RoomRepository roomRepository;
    16	    private final MessageRepository messageRepository;
    17	    private final Map<Class<? extends GuestIdentification>, DocumentGenerator> documentGenerators;
    18	
    19	    public ReservationService(ReservationRepository reservationRepository,
    20	                            RoomRepository roomRepository,
    21	                            MessageRepository messageRepository) {
    22	        this.reservationRepository = reservationRepository;
    23	        this.roomRepository = roomRepository;
    24	        this.messageRepository = messageRepository;
    25	        this.documentGenerators = new HashMap<>();
    26	        this.documentGenerators.put(CpfIdentification.class, new CpfDocumentGenerator());
    27	        this.documentGenerators.put(CnpjIdentification.class, new CnpjDocumentGenerator());
    28	        this.documentGenerators.put(PassportIdentification.class, new PassportDocumentGenerator());
    29	    }
    30	
    31	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
    32	                                       GuestIdentification identification,
    33	                                       LocalDate checkIn, LocalDate checkOut,
    34	                                       int guests, RatePlan ratePlan) {
    35	        Room room = roomRepository.findByNumber(roomNumber)
    36	            .orElseThrow(() -> new RoomNotFoundException());
    37	
    38	        if (guests < 1) {
    39	            throw new InvalidRequestException("Invalid number of guests");
    40	        }
    41	
    42	        if (guests > room.getCapacity()) {
    43	            throw new CapacityExceededException();
    44	        }
    45	
    46	        if (reservationRepository.hasConflict(roomNumber, checkIn, checkOut, null)) {
    47	            throw new RoomUnavailableException();
    48	        }
    49	
    50	        long id = reservationRepository.nextId();
    51	        Reservation reservation = new Reservation(
    52	            id, roomNumber, guestName, guestEmail, identification,
    53	            checkIn, checkOut, guests, ratePlan
    54	        );
    55	
    56	        return reservationRepository.save(reservation);
    57	    }
    58	
    59	    public Reservation confirmReservation(long id) {
    60	        Reservation reservation = reservationRepository.findById(id)
    61	            .orElseThrow(() -> new ReservationNotFoundException());
    62	
    63	        if (!reservation.canConfirm()) {
    64	            throw new OperationNotAllowedException();
    65	        }
    66	
    67	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).get();
    68	        BigDecimal subtotal = reservation.getSubtotal(room.getNightlyRate());
    69	        BigDecimal discount = reservation.getDiscount(subtotal);
    70	        BigDecimal total = reservation.getTotal(subtotal, discount);
    71	
    72	        reservation.confirm(total);
    73	
    74	        Document document = generateDocument(reservation, room, subtotal, discount, total);
    75	        sendConfirmationEmail(reservation, document);
    76	
    77	        return reservation;
    78	    }
    79	
    80	    public Reservation cancelReservation(long id) {
    81	        Reservation reservation = reservationRepository.findById(id)
    82	            .orElseThrow(() -> new ReservationNotFoundException());
    83	
    84	        if (!reservation.canCancel()) {
    85	            throw new OperationNotAllowedException();
    86	        }
    87	
    88	        reservation.cancel();
    89	        return reservation;
    90	    }
    91	
    92	    public Reservation checkIn(long id) {
    93	        Reservation reservation = reservationRepository.findById(id)
    94	            .orElseThrow(() -> new ReservationNotFoundException());
    95	
    96	        if (!reservation.canCheckIn()) {
    97	            throw new OperationNotAllowedException();
    98	        }
    99	
   100	        reservation.checkIn();
   101	        return reservation;
   102	    }
   103	
   104	    public Document checkOut(long id) {
   105	        Reservation reservation = reservationRepository.findById(id)
   106	            .orElseThrow(() -> new ReservationNotFoundException());
   107	
   108	        if (!reservation.canCheckOut()) {
   109	            throw new OperationNotAllowedException();
   110	        }
   111	
   112	        reservation.checkOut();
   113	
   114	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).get();
   115	        BigDecimal subtotal = reservation.getSubtotal(room.getNightlyRate());
   116	        BigDecimal discount = reservation.getDiscount(subtotal);
   117	        BigDecimal total = reservation.getTotal(subtotal, discount);
   118	
   119	        return generateDocument(reservation, room, subtotal, discount, total);
   120	    }
   121	
   122	    public Document getDocument(long id) {
   123	        Reservation reservation = reservationRepository.findById(id)
   124	            .orElseThrow(() -> new ReservationNotFoundException());
   125	
   126	        if (!reservation.isPaid()) {
   127	            throw new OperationNotAllowedException();
   128	        }
   129	
   130	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).get();
   131	        BigDecimal subtotal = reservation.getSubtotal(room.getNightlyRate());
   132	        BigDecimal discount = reservation.getDiscount(subtotal);
   133	        BigDecimal total = reservation.getTotal(subtotal, discount);
   134	
   135	        return generateDocument(reservation, room, subtotal, discount, total);
   136	    }
   137	
   138	    private Document generateDocument(Reservation reservation, Room room,
   139	                                     BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
   140	        DocumentGenerator generator = documentGenerators.get(reservation.getIdentification().getClass());
   141	        return generator.generate(reservation, room, subtotal, discount, total);
   142	    }
   143	
   144	    private void sendConfirmationEmail(Reservation reservation, Document document) {
   145	        String subject = "Reserva confirmada - Pousada Maré Alta";
   146	        String body = "Olá, " + reservation.getGuestName() + "!\n\n" +
   147	                     "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
   148	                     document.getText() + "\n\n" +
   149	                     "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
   150	                     "Até breve!";
   151	
   152	        long messageId = messageRepository.nextId();
   153	        Message message = new Message(messageId, "EMAIL", reservation.getGuestEmail(), subject, body);
   154	        messageRepository.save(message);
   155	    }
   156	}

