     8	public class Reservation {
     9	    private final long id;
    10	    private final String roomNumber;
    11	    private final String guestName;
    12	    private final String guestEmail;
    13	    private final GuestIdentification identification;
    14	    private final LocalDate checkIn;
    15	    private final LocalDate checkOut;
    16	    private final int guests;
    17	    private final RatePlan ratePlan;
    18	    private ReservationStatus status;
    19	    private BigDecimal amountPaid;
    20	    private BigDecimal refund;
    21	
    22	    public Reservation(long id, String roomNumber, String guestName, String guestEmail,
    23	                       GuestIdentification identification, LocalDate checkIn, LocalDate checkOut,
    24	                       int guests, RatePlan ratePlan) {
    25	        this.id = id;
    26	        this.roomNumber = roomNumber;
    27	        this.guestName = guestName;
    28	        this.guestEmail = guestEmail;
    29	        this.identification = identification;
    30	        this.checkIn = checkIn;
    31	        this.checkOut = checkOut;
    32	        this.guests = guests;
    33	        this.ratePlan = ratePlan;
    34	        this.status = ReservationStatus.PENDING;
    35	        this.amountPaid = BigDecimal.ZERO;
    36	        this.refund = null;
    37	    }
    38	
    39	    public long getId() {
    40	        return id;
    41	    }
    42	
    43	    public String getRoomNumber() {
    44	        return roomNumber;
    45	    }
    46	
    47	    public String getGuestName() {
    48	        return guestName;
    49	    }
    50	
    51	    public String getGuestEmail() {
    52	        return guestEmail;
    53	    }
    54	
    55	    public GuestIdentification getIdentification() {
    56	        return identification;
    57	    }
    58	
    59	    public LocalDate getCheckIn() {
    60	        return checkIn;
    61	    }
    62	
    63	    public LocalDate getCheckOut() {
    64	        return checkOut;
    65	    }
    66	
    67	    public int getGuests() {
    68	        return guests;
    69	    }
    70	
    71	    public RatePlan getRatePlan() {
    72	        return ratePlan;
    73	    }
    74	
    75	    public ReservationStatus getStatus() {
    76	        return status;
    77	    }
    78	
    79	    public BigDecimal getAmountPaid() {
    80	        return amountPaid;
    81	    }
    82	
    83	    public BigDecimal getRefund() {
    84	        return refund;
    85	    }
    86	
    87	    public int getNights() {
    88	        return (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    89	    }
    90	
    91	    public BigDecimal getSubtotal(BigDecimal nightlyRate) {
    92	        BigDecimal sum = BigDecimal.ZERO;
    93	        LocalDate date = checkIn;
    94	        while (date.isBefore(checkOut)) {
    95	            BigDecimal nightRate = nightlyRate;
    96	            if (isHighSeason(date)) {
    97	                nightRate = nightRate.multiply(new BigDecimal("1.20"))
    98	                    .setScale(2, RoundingMode.HALF_EVEN);
    99	            }
   100	            sum = sum.add(nightRate);
   101	            date = date.plusDays(1);
   102	        }
   103	        return sum.setScale(2, RoundingMode.HALF_EVEN);
   104	    }
   105	
   106	    public BigDecimal getDiscount(BigDecimal subtotal) {
   107	        return subtotal.multiply(ratePlan.getDiscountRate())
   108	            .setScale(2, RoundingMode.HALF_EVEN);
   109	    }
   110	
   111	    public BigDecimal getTotal(BigDecimal subtotal, BigDecimal discount) {
   112	        return subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
   113	    }
   114	
   115	    private boolean isHighSeason(LocalDate date) {
   116	        int month = date.getMonthValue();
   117	        int day = date.getDayOfMonth();
   118	
   119	        if (month == 7) {
   120	            return true;
   121	        }
   122	        if (month == 12 && day >= 15) {
   123	            return true;
   124	        }
   125	        if (month == 1 || month == 2) {
   126	            return true;
   127	        }
   128	        return false;
