     8	import java.math.BigDecimal;
     9	import java.time.LocalDate;
    10	import java.time.YearMonth;
    11	import java.time.format.DateTimeFormatter;
    12	import java.util.Comparator;
    13	import java.util.List;
    14	
    15	public class ReportService {
    16	    private final ReservationRepository reservationRepository;
    17	    private final RoomRepository roomRepository;
    18	
    19	    public ReportService(ReservationRepository reservationRepository, RoomRepository roomRepository) {
    20	        this.reservationRepository = reservationRepository;
    21	        this.roomRepository = roomRepository;
    22	    }
    23	
    24	    public String generateOccupancyReport(LocalDate date) {
    25	        StringBuilder csv = new StringBuilder();
    26	        csv.append("room,type,reservation,check_in,check_out\n");
    27	
    28	        List<Reservation> occupiedReservations = reservationRepository.findAll().stream()
    29	            .filter(r -> r.isPaid())
    30	            .filter(r -> r.occupiesNight(date))
    31	            .sorted(Comparator.comparing(Reservation::getRoomNumber))
    32	            .toList();
    33	
    34	        for (Reservation reservation : occupiedReservations) {
    35	            Room room = roomRepository.findByNumber(reservation.getRoomNumber()).get();
    36	            csv.append(room.getNumber()).append(",");
    37	            csv.append(room.getType()).append(",");
    38	            csv.append(reservation.getId()).append(",");
    39	            csv.append(reservation.getCheckIn().format(DateTimeFormatter.ISO_LOCAL_DATE)).append(",");
    40	            csv.append(reservation.getCheckOut().format(DateTimeFormatter.ISO_LOCAL_DATE)).append("\n");
    41	        }
    42	
    43	        int totalRooms = roomRepository.findAll().size();
    44	        csv.append("total,").append(occupiedReservations.size()).append("/").append(totalRooms);
    45	
    46	        return csv.toString();
    47	    }
    48	
    49	    public String generateRevenueReport(YearMonth month) {
    50	        StringBuilder csv = new StringBuilder();
    51	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    52	
    53	        List<Reservation> monthReservations = reservationRepository.findAll().stream()
    54	            .filter(r -> YearMonth.from(r.getCheckIn()).equals(month))
    55	            .sorted(Comparator.comparing(Reservation::getCheckIn)
    56	                .thenComparing(Reservation::getId))
    57	            .toList();
    58	
    59	        BigDecimal totalRevenue = BigDecimal.ZERO;
    60	
    61	        for (Reservation reservation : monthReservations) {
    62	            BigDecimal revenue = calculateRevenue(reservation);
    63	            if (revenue.compareTo(BigDecimal.ZERO) > 0) {
    64	                csv.append(reservation.getId()).append(",");
    65	                csv.append(reservation.getRoomNumber()).append(",");
    66	                csv.append(reservation.getCheckIn().format(DateTimeFormatter.ISO_LOCAL_DATE)).append(",");
    67	                csv.append(reservation.getCheckOut().format(DateTimeFormatter.ISO_LOCAL_DATE)).append(",");
    68	                csv.append(reservation.getStatus()).append(",");
    69	                csv.append(String.format("%.2f", revenue)).append("\n");
    70	                totalRevenue = totalRevenue.add(revenue);
    71	            }
    72	        }
    73	
    74	        csv.append("total,").append(String.format("%.2f", totalRevenue));
    75	
    76	        return csv.toString();
    77	    }
    78	
    79	    private BigDecimal calculateRevenue(Reservation reservation) {
    80	        BigDecimal paid = reservation.getAmountPaid();
    81	        BigDecimal refunded = reservation.getRefund() != null ? reservation.getRefund() : BigDecimal.ZERO;
    82	        return paid.subtract(refunded);
    83	    }
    84	}

